-- Cubby House (ages 1-2) Advent programme, from Cubby_House_Advent_Programme_Ages_1-2_updated.pdf
-- Safe to run more than once: existing rows for the same group and date are updated.
INSERT INTO public.lessons (group_slug, lesson_date, title_en, title_de, verses_en, verses_de, idea_en, idea_de, story_en, story_de, questions_en, questions_de, published) VALUES
('cubby-house','2026-11-29','Hope: God Keeps His Promises','Hoffnung: Gott hält seine Versprechen','Luke 1:26–38','Lukas 1,26–38','God promised to send Jesus, and He did!','Gott hat versprochen, Jesus zu senden – und er hat es getan!','One day, God sent an angel named Gabriel to visit a young woman named Mary. The angel said, “Hello, Mary! God has a very special plan for you.” Mary listened carefully. The angel told her that she would have a baby boy, and His name would be Jesus! Jesus was God’s special promise to the world. God promised to send Jesus, and He kept His promise! Mary trusted God and said, “Yes, I will do what God says.” And do you know what? God always keeps His promises! We can have hope because we know that God keeps His promises too!

Craft: make a Christmas candle. Carol: Joy to the World. Dress code: Santa / Christmas hats.','Eines Tages schickte Gott einen Engel namens Gabriel zu einer jungen Frau namens Maria. Der Engel sagte: „Hallo, Maria! Gott hat einen ganz besonderen Plan für dich.“ Maria hörte aufmerksam zu. Der Engel erzählte ihr, dass sie einen kleinen Jungen bekommen würde, und sein Name sollte Jesus sein! Jesus war Gottes besonderes Versprechen an die Welt. Gott hatte versprochen, Jesus zu senden, und er hielt sein Versprechen! Maria vertraute Gott und sagte: „Ja, ich will tun, was Gott sagt.“ Und weißt du was? Gott hält immer seine Versprechen! Wir können Hoffnung haben, weil wir wissen, dass Gott auch unsere Versprechen hält!

Basteln: eine Weihnachtskerze. Lied: Joy to the World. Dresscode: Nikolaus- / Weihnachtsmützen.',ARRAY['God always keeps His promises.','God promised to send Jesus. We can trust God!','Light an electric candle together and say: “Jesus is the light of the world!”'],ARRAY['Gott hält immer seine Versprechen.','Gott hat versprochen, Jesus zu senden. Wir können Gott vertrauen!','Zündet gemeinsam eine elektrische Kerze an und sagt: „Jesus ist das Licht der Welt!“'],true),
('cubby-house','2026-12-06','Peace: Jesus Is Our Peace','Frieden: Jesus ist unser Friede','John 14:27','Johannes 14,27','Jesus brings us peace. We can trust Him with everything.','Jesus schenkt uns Frieden. Wir können ihm alles anvertrauen.','Sometimes we feel scared. Sometimes we feel sad. Sometimes we don’t know what will happen. But do you know something very special? Jesus loves us, and He is always with us! When we feel scared, we can talk to Jesus. When we feel worried, we can trust Him. Jesus gives us peace in our hearts. He helps us feel safe because He is always with us. Jesus brings us peace, and we can trust Him with everything!

Craft: make a white dove. Carol: Joy to the World. Dress code: Santa / Christmas hats.','Manchmal haben wir Angst. Manchmal sind wir traurig. Manchmal wissen wir nicht, was passieren wird. Aber weißt du etwas ganz Besonderes? Jesus hat uns lieb und ist immer bei uns! Wenn wir Angst haben, können wir mit Jesus reden. Wenn wir uns Sorgen machen, können wir ihm vertrauen. Jesus schenkt uns Frieden im Herzen. Er hilft uns, uns sicher zu fühlen, weil er immer bei uns ist. Jesus schenkt uns Frieden, und wir können ihm alles anvertrauen!

Basteln: eine weiße Taube. Lied: Joy to the World. Dresscode: Nikolaus- / Weihnachtsmützen.',ARRAY['Jesus is always with us.','We can talk to Jesus when we feel scared.','Open and flap your arms like a little dove and say: “Jesus gives me peace!”'],ARRAY['Jesus ist immer bei uns.','Wir können mit Jesus reden, wenn wir Angst haben.','Breitet die Arme aus und flattert wie eine kleine Taube: „Jesus schenkt mir Frieden!“'],true),
('cubby-house','2026-12-13','Joy: Jesus Is Born!','Freude: Jesus ist geboren!','Luke 2:1–11','Lukas 2,1–11','Jesus brings us great joy!','Jesus schenkt uns große Freude!','Mary and Joseph travelled to a town called Bethlehem. While they were there, it was time for baby Jesus to be born. Mary wrapped baby Jesus in soft cloths and laid Him in a manger because there was no room for them in the inn. Nearby, some shepherds were looking after their sheep. Suddenly, an angel appeared and said, “Don’t be afraid! I have good news that will bring great joy to everyone! Today, a special baby has been born. His name is Jesus!” The shepherds were so excited! Jesus was born! What wonderful news! Jesus brings us great joy because He is God’s special gift to the world!

Craft: make a Christmas tree with little angel decorations. Carol: Joy to the World. Dress code: Santa / Christmas hats.','Maria und Josef reisten in eine Stadt namens Betlehem. Als sie dort waren, war es Zeit, dass das Jesuskind geboren wurde. Maria wickelte das Baby Jesus in weiche Tücher und legte es in eine Krippe, weil in der Herberge kein Platz für sie war. In der Nähe hüteten Hirten ihre Schafe. Plötzlich erschien ein Engel und sagte: „Fürchtet euch nicht! Ich habe eine gute Nachricht, die allen große Freude bringt! Heute ist ein besonderes Baby geboren worden. Sein Name ist Jesus!“ Die Hirten freuten sich riesig! Jesus ist geboren! Was für eine wunderbare Nachricht! Jesus schenkt uns große Freude, weil er Gottes besonderes Geschenk an die Welt ist!

Basteln: ein Weihnachtsbaum mit kleinen Engeln. Lied: Joy to the World. Dresscode: Nikolaus- / Weihnachtsmützen.',ARRAY['Jesus was born in Bethlehem.','Jesus is God’s special gift.','Celebrate Jesus by clapping, smiling and dancing to the Christmas carol!'],ARRAY['Jesus wurde in Betlehem geboren.','Jesus ist Gottes besonderes Geschenk.','Feiert Jesus mit Klatschen, Lächeln und Tanzen zum Weihnachtslied!'],true),
('cubby-house','2026-12-20','Love: The Shepherds Hear About Jesus','Liebe: Die Hirten hören von Jesus','Luke 2:8–20','Lukas 2,8–20','God loves us so much that He gave us Jesus!','Gott liebt uns so sehr, dass er uns Jesus geschenkt hat!','One night, some shepherds were outside looking after their sheep. Suddenly, a bright light appeared, and an angel came to visit them! The shepherds were afraid, but the angel said, “Don’t be afraid! I have wonderful news! Jesus has been born!” The angel told them where to find baby Jesus. The shepherds were so excited! They went quickly to Bethlehem and found Mary, Joseph and baby Jesus lying in a manger. They were so happy to see Him! God sent Jesus because He loves us so much. Jesus is God’s special gift to us. God loves you, God loves me, and God loves everyone! And that’s why we celebrate Christmas!

Craft: make a heart with a cross. Carol: Joy to the World. Dress code: ugly Christmas sweaters.','In einer Nacht hüteten Hirten draußen ihre Schafe. Plötzlich erschien ein helles Licht, und ein Engel kam zu ihnen! Die Hirten fürchteten sich, aber der Engel sagte: „Fürchtet euch nicht! Ich habe wunderbare Neuigkeiten! Jesus ist geboren!“ Der Engel sagte ihnen, wo sie das Jesuskind finden würden. Die Hirten freuten sich riesig! Sie liefen schnell nach Betlehem und fanden Maria, Josef und das Baby Jesus in der Krippe. Sie waren so glücklich, ihn zu sehen! Gott hat Jesus gesandt, weil er uns so sehr liebt. Jesus ist Gottes besonderes Geschenk an uns. Gott liebt dich, Gott liebt mich, und Gott liebt alle! Und deshalb feiern wir Weihnachten!

Basteln: ein Herz mit einem Kreuz. Lied: Joy to the World. Dresscode: hässliche Weihnachtspullover.',ARRAY['God loves us so much.','Jesus is God’s special gift. We can share God’s love with others.','Hold up a big heart and say together: “God loves me!”'],ARRAY['Gott liebt uns so sehr.','Jesus ist Gottes besonderes Geschenk. Wir können Gottes Liebe mit anderen teilen.','Haltet ein großes Herz hoch und sagt gemeinsam: „Gott liebt mich!“'],true)
